18	    /// Disallow the use of inline styles.
19	    ///
20	    /// Inline styles via the `style` attribute make code harder to maintain and override,
21	    /// prevent reusability of styling, and can be a security concern when implementing
22	    /// a strict Content Security Policy (CSP).
23	    ///
24	    /// Instead of inline styles, use CSS classes, CSS modules, or a styling library.
25	    ///
26	    /// ## Examples
27	    ///
28	    /// ### Invalid
29	    ///
30	    /// ```jsx,expect_diagnostic
31	    /// <div style={{ color: "red" }}>Error</div>
32	    /// ```
33	    ///
34	    /// ```js,expect_diagnostic
35	    /// React.createElement("div", { style: { color: "red" } });
36	    /// ```
37	    ///
38	    /// ### Valid
39	    ///
40	    /// ```jsx
41	    /// <div className="text-red">Error</div>
42	    /// ```
43	    ///
44	    /// ```js
45	    /// React.createElement("div", { className: "container" });
46	    /// ```
47	    ///
48	    /// ## Resources
49	    ///
50	    /// - [Content Security Policy: Allowing inline styles](https://content-security-policy.com/examples/allow-inline-style)
51	    ///
52	    pub NoInlineStyles {
53	        version: "2.4.9",
54	        name: "noInlineStyles",
55	        language: "js",
56	        recommended: false,
57	        fix_kind: FixKind::Unsafe,
58	    }
59	}
