61	impl Rule for NoInlineStyles {
62	    type Query = Semantic<NoInlineStylesQuery>;
63	    type State = TextRange;
64	    type Signals = Option<Self::State>;
65	    type Options = NoInlineStylesOptions;
66	
67	    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
68	        let node = ctx.query();
69	
70	        match node {
71	            NoInlineStylesQuery::AnyJsxElement(element) => {
72	                let attribute = find_style_attribute(element)?;
73	                Some(attribute.range())
74	            }
75	            NoInlineStylesQuery::JsCallExpression(call_expression) => {
76	                let model = ctx.model();
77	                let object_member = find_style_object_member(call_expression, model)?;
78	                Some(object_member.range())
79	            }
80	        }
81	    }
82	
83	    fn diagnostic(_ctx: &RuleContext<Self>, state: &Self::State) -> Option<RuleDiagnostic> {
84	        Some(
85	            RuleDiagnostic::new(
86	                rule_category!(),
87	                state,
88	                markup! {
89	                    "Unexpected "<Emphasis>"style"</Emphasis>" attribute."
90	                },
91	            )
92	            .note(markup! {
93	                "Inline styles make code harder to maintain, reduce reusability, and can prevent effective use of a strict Content Security Policy. Use external CSS classes or stylesheets instead."
94	            }),
95	        )
96	    }
97	
98	    fn action(ctx: &RuleContext<Self>, _state: &Self::State) -> Option<JsRuleAction> {
99	        let node = ctx.query();
100	        let mut mutation = ctx.root().begin();
101	        match node {
102	            NoInlineStylesQuery::AnyJsxElement(element) => {
103	                let attribute = find_style_attribute(element)?;
104	                mutation.remove_node(attribute);
105	            }
106	            NoInlineStylesQuery::JsCallExpression(call_expression) => {
107	                let model = ctx.model();
108	                let object_member = find_style_object_member(call_expression, model)?;
109	                mutation.remove_js_object_member(AnyJsObjectMember::JsPropertyObjectMember(
110	                    object_member,
111	                ));
112	            }
113	        }
114	
115	        Some(JsRuleAction::new(
116	            ctx.metadata().action_category(ctx.category(), ctx.group()),
117	            ctx.metadata().applicability(),
118	            markup! { "Remove the "<Emphasis>"style"</Emphasis>" attribute." }.to_owned(),
119	            mutation,
120	        ))
121	    }
122	}
