132	fn find_style_object_member(
133	    call_expression: &JsCallExpression,
134	    model: &SemanticModel,
135	) -> Option<JsPropertyObjectMember> {
136	    let react_create_element =
137	        ReactCreateElementCall::from_call_expression(call_expression, model)?;
138	
139	    if react_create_element.is_custom_component() {
140	        return None;
141	    }
142	
143	    let ReactCreateElementCall { props, .. } = react_create_element;
144	    let props = props?;
145	
146	    for member in props.members() {
147	        if let Some(member) = member.ok()
148	            && let Some(member) = member.as_js_property_object_member()
149	            && let Some(name) = member.name().ok()
150	            && let Some(name) = name.as_js_literal_member_name()
151	            && let Some(value) = name.value().ok()
152	            && is_style_value(&value)
153	        {
154	            return Some(member.clone());
155	        }
156	    }
157	
158	    None
159	}
