161	fn find_style_attribute(any_opening: &AnyJsxElement) -> Option<JsxAttribute> {
162	    if any_opening.is_custom_component() {
163	        return None;
164	    }
165	
166	    for attribute in any_opening.attributes() {
167	        if let Some(attribute) = attribute.as_jsx_attribute()
168	            && let Some(name) = attribute.name().ok()
169	            && let Some(name) = name.as_jsx_name()
170	            && let Some(value_token) = name.value_token().ok()
171	            && is_style_value(&value_token)
172	        {
173	            return Some(attribute.clone());
174	        }
175	    }
176	
177	    None
178	}
